src/hooks/ops/useOpsBookingStatusActions:
'use client';

import { useMutation, useQueryClient, type UseMutationResult } from '@tanstack/react-query';

import { useTransitionToast, useBookingErrorBoundary } from '@/components/features/booking-state-machine';
import { useBookingOfflineQueue } from '@/contexts/booking-offline-queue';
import { useOptionalBookingStateMachine } from '@/contexts/booking-state-machine';
import { useBookingService } from '@/contexts/ops-services';
import { HttpError } from '@/lib/http/errors';
import { queryKeys } from '@/lib/query/keys';

import type { OpsBookingStatus, OpsTodayBooking, OpsTodayBookingsSummary } from '@/types/ops';

export type BookingLifecycleVariables = {
  restaurantId: string;
  bookingId: string;
  performedAt?: string | null;
  targetDate?: string | null;
};

export type BookingLifecycleWithReasonVariables = BookingLifecycleVariables & {
  reason?: string | null;
};

type LifecycleMutationResult = {
  status: OpsBookingStatus;
  checkedInAt: string | null;
  checkedOutAt: string | null;
};

type MutationContext = {
  bookingId: string;
  summaryKey?: ReturnType<(typeof queryKeys)['opsDashboard']['summary']>;
  previousSummary?: OpsTodayBookingsSummary;
};

type OfflineActionType = 'check-in' | 'check-out' | 'no-show' | 'undo-no-show';

function useInvalidateLifecycle(queryClient: ReturnType<typeof useQueryClient>) {
  return (
    restaurantId: string,
    targetDate?: string | null,
    options?: { invalidateSummary?: boolean; refetchSummary?: boolean },
  ) => {
    const summaryKey = queryKeys.opsDashboard.summary(restaurantId, targetDate ?? null);
    if (options?.invalidateSummary) {
      queryClient.invalidateQueries({
        queryKey: summaryKey,
        // The ops summary endpoint is server-cached (default ~5s) and can return stale data immediately after a mutation.
        // Avoid refetching the active summary query right away to prevent "bounce back" overwrites of optimistic cache.
        refetchType: options.refetchSummary ? 'active' : 'none',
      });
    }
    queryClient.invalidateQueries({ queryKey: ['ops', 'dashboard', restaurantId, 'heatmap'], exact: false });
    queryClient.invalidateQueries({ queryKey: ['ops', 'bookings'], exact: false });
  };
}

function toPayloadTimestamp(value?: string | null): string | undefined {
  if (!value) return undefined;
  return value;
}

export function useOpsBookingLifecycleActions() {
  const bookingService = useBookingService();
  const queryClient = useQueryClient();
  const invalidate = useInvalidateLifecycle(queryClient);
  const bookingStateMachine = useOptionalBookingStateMachine();
  const transitionToast = useTransitionToast();
  const bookingErrorBoundary = useBookingErrorBoundary();
  const offlineQueue = useBookingOfflineQueue();

  const maybeQueueOffline = <TVariables extends { bookingId: string }>(
    action: OfflineActionType,
    variables: TVariables,
    label: string,
    executor: () => Promise<unknown>,
  ): boolean => {
    if (!offlineQueue || !offlineQueue.isOffline) {
      return false;
    }
    offlineQueue.enqueue({
      bookingId: variables.bookingId,
      action,
      label,
      perform: executor,
    });
    transitionToast.showQueued({
      action,
      bookingLabel: variables.bookingId,
    });
    return true;
  };

  const handleConflict = (
    error: Error,
    variables: { bookingId: string; restaurantId?: string | null; targetDate?: string | null },
    attemptedStatus: OpsBookingStatus,
  ): boolean => {
    if (!(error instanceof HttpError) || error.status !== 409 || !bookingErrorBoundary) {
      return false;
    }
    const entry = bookingStateMachine?.getEntry(variables.bookingId);
    const details = (error.details as Record<string, unknown> | undefined) ?? {};
    const detailsStatus = (details?.currentStatus ?? details?.status) as OpsBookingStatus | undefined;
    const detailsUpdatedAt = typeof details?.updatedAt === 'string' ? (details.updatedAt as string) : undefined;

    bookingErrorBoundary.reportConflict({
      bookingId: variables.bookingId,
      attemptedStatus,
      currentStatus: detailsStatus ?? entry?.status ?? null,
      message: error.message,
      updatedAt: detailsUpdatedAt ?? entry?.updatedAt ?? null,
      onReload:
        variables.restaurantId && typeof variables.restaurantId === 'string'
          ? () =>
              invalidate(variables.restaurantId as string, variables.targetDate ?? null, {
                invalidateSummary: true,
                refetchSummary: true,
              })
          : null,
    });
    return true;
  };

  const wrapMutation = <TData, TError, TVariables extends { bookingId: string }, TContext>(
    mutation: UseMutationResult<TData, TError, TVariables, TContext>,
    config: { action: OfflineActionType; label: (variables: TVariables) => string },
  ): typeof mutation => {
    const mutate: typeof mutation.mutate = (variables, options) => {
      const queued = maybeQueueOffline(config.action, variables, config.label(variables), () =>
        mutation.mutateAsync(variables, options as Parameters<typeof mutation.mutateAsync>[1]),
      );
      if (queued) {
        return;
      }
      mutation.mutate(variables, options);
    };

    const mutateAsync: typeof mutation.mutateAsync = async (variables, options) => {
      const queued = maybeQueueOffline(config.action, variables, config.label(variables), () =>
        mutation.mutateAsync(variables, options),
      );
      if (queued) {
        return Promise.resolve(undefined as TData) as Promise<TData>;
      }
      return mutation.mutateAsync(variables, options);
    };

    return {
      ...mutation,
      mutate,
      mutateAsync,
    };
  };

  const applyOptimisticTransition = async (
    bookingId: string,
    expectedStatus: OpsBookingStatus,
    variables: { restaurantId?: string | null; targetDate?: string | null },
    patch: (booking: OpsTodayBooking) => OpsTodayBooking,
    meta: Record<string, unknown>,
  ): Promise<MutationContext> => {
    let summaryKey: ReturnType<(typeof queryKeys)['opsDashboard']['summary']> | undefined;
    let previousSummary: OpsTodayBookingsSummary | undefined;

    if (variables.restaurantId) {
      summaryKey = queryKeys.opsDashboard.summary(variables.restaurantId, variables.targetDate ?? null);

      // Cancel any in-flight refetches to prevent them from overwriting our optimistic update
      await queryClient.cancelQueries({ queryKey: summaryKey });

      const currentSummary = queryClient.getQueryData<OpsTodayBookingsSummary>(summaryKey);
      if (currentSummary) {
        previousSummary = currentSummary;
        const updatedSummary: OpsTodayBookingsSummary = {
          ...currentSummary,
          bookings: currentSummary.bookings.map((booking) =>
            booking.id === bookingId ? patch({ ...booking }) : booking,
          ),
        };
        queryClient.setQueryData(summaryKey, updatedSummary);
      }
    }

    bookingStateMachine?.beginTransition(bookingId, expectedStatus, meta);

    return { bookingId, summaryKey, previousSummary };
  };

  const rollbackOptimisticTransition = (bookingId: string, context?: MutationContext) => {
    if (context?.summaryKey && context.previousSummary) {
      queryClient.setQueryData(context.summaryKey, context.previousSummary);
    }
    bookingStateMachine?.rollbackTransition(bookingId);
  };

  const commitOptimisticTransition = (
    bookingId: string,
    context: MutationContext | undefined,
    snapshot: { status: OpsBookingStatus; checkedInAt?: string | null; checkedOutAt?: string | null; updatedAt?: string | null },
  ) => {
    if (context?.summaryKey) {
      queryClient.setQueryData<OpsTodayBookingsSummary>(context.summaryKey, (current) => {
        if (!current) return current;
        return {
          ...current,
          bookings: current.bookings.map((booking) => {
            if (booking.id !== bookingId) {
              return booking;
            }
            const next: OpsTodayBooking = {
              ...booking,
              status: snapshot.status,
            };
            if (snapshot.checkedInAt !== undefined) {
              next.checkedInAt = snapshot.checkedInAt;
            }
            if (snapshot.checkedOutAt !== undefined) {
              next.checkedOutAt = snapshot.checkedOutAt;
            }
            return next;
          }),
        };
      });
    }

    bookingStateMachine?.commitTransition({
      id: bookingId,
      status: snapshot.status,
      updatedAt: snapshot.updatedAt ?? null,
    });
  };

  const checkInMutation = useMutation<LifecycleMutationResult, Error, BookingLifecycleVariables, MutationContext>({
    mutationFn: ({ bookingId, performedAt }) =>
      bookingService.checkInBooking({ id: bookingId, performedAt: toPayloadTimestamp(performedAt) }),
    onMutate: async (variables) => {
      const performedAt = variables.performedAt ?? new Date().toISOString();
      return await applyOptimisticTransition(
        variables.bookingId,
        'checked_in',
        { restaurantId: variables.restaurantId, targetDate: variables.targetDate ?? null },
        (booking) => ({
          ...booking,
          status: 'checked_in',
          checkedInAt: performedAt,
          checkedOutAt: null,
        }),
        { action: 'check-in', performedAt },
      );
    },
    onSuccess: (updated, variables, context) => {
      commitOptimisticTransition(variables.bookingId, context, {
        status: updated.status,
        checkedInAt: updated.checkedInAt,
        checkedOutAt: updated.checkedOutAt,
      });
      invalidate(variables.restaurantId, variables.targetDate ?? null);
      transitionToast.showSuccess({ action: 'check-in' });
    },
    onError: (error, variables, context) => {
      rollbackOptimisticTransition(variables.bookingId, context);
      if (handleConflict(error, variables, 'checked_in')) {
        return;
      }
      transitionToast.showError({
        action: 'check-in',
        errorMessage: error.message || 'Failed to check in guest',
      });
    },
  });

  const checkOutMutation = useMutation<LifecycleMutationResult, Error, BookingLifecycleVariables, MutationContext>({
    mutationFn: ({ bookingId, performedAt }) =>
      bookingService.checkOutBooking({ id: bookingId, performedAt: toPayloadTimestamp(performedAt) }),
    onMutate: async (variables) => {
      const performedAt = variables.performedAt ?? new Date().toISOString();
      return await applyOptimisticTransition(
        variables.bookingId,
        'completed',
        { restaurantId: variables.restaurantId, targetDate: variables.targetDate ?? null },
        (booking) => ({
          ...booking,
          status: 'completed',
          checkedOutAt: performedAt,
        }),
        { action: 'check-out', performedAt },
      );
    },
    onSuccess: (updated, variables, context) => {
      commitOptimisticTransition(variables.bookingId, context, {
        status: updated.status,
        checkedInAt: updated.checkedInAt,
        checkedOutAt: updated.checkedOutAt,
      });
      invalidate(variables.restaurantId, variables.targetDate ?? null);
      transitionToast.showSuccess({ action: 'check-out' });
    },
    onError: (error, variables, context) => {
      rollbackOptimisticTransition(variables.bookingId, context);
      if (handleConflict(error, variables, 'completed')) {
        return;
      }
      transitionToast.showError({
        action: 'check-out',
        errorMessage: error.message || 'Failed to check out guest',
      });
    },
  });

  const markNoShowMutation = useMutation<LifecycleMutationResult, Error, BookingLifecycleWithReasonVariables, MutationContext>({
    mutationFn: ({ bookingId, performedAt, reason }) =>
      bookingService.markNoShowBooking({
        id: bookingId,
        performedAt: toPayloadTimestamp(performedAt),
        reason: reason ?? undefined,
      }),
    onMutate: async (variables) => {
      const performedAt = variables.performedAt ?? null;
      return await applyOptimisticTransition(
        variables.bookingId,
        'no_show',
        { restaurantId: variables.restaurantId, targetDate: variables.targetDate ?? null },
        (booking) => ({
          ...booking,
          status: 'no_show',
          checkedOutAt: booking.checkedOutAt,
          checkedInAt: booking.checkedInAt,
        }),
        { action: 'mark-no-show', performedAt },
      );
    },
    onSuccess: (updated, variables, context) => {
      commitOptimisticTransition(variables.bookingId, context, {
        status: updated.status,
        checkedInAt: updated.checkedInAt,
        checkedOutAt: updated.checkedOutAt,
      });
      invalidate(variables.restaurantId, variables.targetDate ?? null);
      transitionToast.showSuccess({ action: 'no-show' });
    },
    onError: (error, variables, context) => {
      rollbackOptimisticTransition(variables.bookingId, context);
      if (handleConflict(error, variables, 'no_show')) {
        return;
      }
      transitionToast.showError({
        action: 'no-show',
        errorMessage: error.message || 'Failed to mark booking as no-show',
      });
    },
  });

  const undoNoShowMutation = useMutation<LifecycleMutationResult, Error, BookingLifecycleWithReasonVariables, MutationContext>({
    mutationFn: ({ bookingId, reason }) =>
      bookingService.undoNoShowBooking({
        id: bookingId,
        reason: reason ?? undefined,
      }),
    onMutate: async (variables) => {
      return await applyOptimisticTransition(
        variables.bookingId,
        'confirmed',
        { restaurantId: variables.restaurantId, targetDate: variables.targetDate ?? null },
        (booking) => ({
          ...booking,
          status: 'confirmed',
        }),
        { action: 'undo-no-show' },
      );
    },
    onSuccess: (updated, variables, context) => {
      commitOptimisticTransition(variables.bookingId, context, {
        status: updated.status,
        checkedInAt: updated.checkedInAt,
        checkedOutAt: updated.checkedOutAt,
      });
      invalidate(variables.restaurantId, variables.targetDate ?? null);
      transitionToast.showSuccess({ action: 'undo-no-show' });
    },
    onError: (error, variables, context) => {
      rollbackOptimisticTransition(variables.bookingId, context);
      if (handleConflict(error, variables, 'confirmed')) {
        return;
      }
      transitionToast.showError({
        action: 'undo-no-show',
        errorMessage: error.message || 'Failed to undo no-show',
      });
    },
  });

  const checkIn = wrapMutation(checkInMutation, {
    action: 'check-in',
    label: () => 'Check in',
  });
  const checkOut = wrapMutation(checkOutMutation, {
    action: 'check-out',
    label: () => 'Check out',
  });
  const markNoShow = wrapMutation(markNoShowMutation, {
    action: 'no-show',
    label: () => 'Mark no-show',
  });
  const undoNoShow = wrapMutation(undoNoShowMutation, {
    action: 'undo-no-show',
    label: () => 'Undo no-show',
  });

  return {
    checkIn,
    checkOut,
    markNoShow,
    undoNoShow,
  };
}

export const useOpsBookingStatusActions = useOpsBookingLifecycleActions;

src/hooks/ops/useOpsBookingStatusSummary:
'use client';

import { useQuery } from '@tanstack/react-query';
import { useMemo } from 'react';

import { useBookingService } from '@/contexts/ops-services';
import { toIsoDateParam } from '@/hooks/ops/utils/toIsoDateParam';
import { HttpError } from '@/lib/http/errors';

import type { OpsBookingStatus } from '@/types/ops';

type UseOpsBookingStatusSummaryOptions = {
  restaurantId: string | null;
  from?: Date | string | null;
  to?: Date | string | null;
  statuses?: OpsBookingStatus[];
  enabled?: boolean;
};

export function useOpsBookingStatusSummary({
  restaurantId,
  from,
  to,
  statuses,
  enabled = true,
}: UseOpsBookingStatusSummaryOptions) {
  const bookingService = useBookingService();

  const queryKey = useMemo(() => {
    const fromIso = toIsoDateParam(from);
    const toIsoValue = toIsoDateParam(to);
    const normalizedStatuses = statuses && statuses.length > 0 ? [...new Set(statuses)].sort() : [];

    return [
      'ops',
      'bookings',
      'status-summary',
      restaurantId ?? 'none',
      fromIso,
      toIsoValue,
      normalizedStatuses.join(','),
    ] as const;
  }, [restaurantId, from, to, statuses]);

  return useQuery({
    queryKey,
    enabled: enabled && Boolean(restaurantId),
    queryFn: async () => {
      if (!restaurantId) {
        throw new Error('Restaurant is required');
      }

      const fromIso = toIsoDateParam(from);
      const toIsoValue = toIsoDateParam(to);
      const normalizedStatuses = statuses && statuses.length > 0 ? statuses : undefined;

      try {
        return await bookingService.getStatusSummary({
          restaurantId,
          from: fromIso ?? undefined,
          to: toIsoValue ?? undefined,
          statuses: normalizedStatuses,
        });
      } catch (error) {
        if (error instanceof HttpError && error.status === 404) {
          return {
            restaurantId,
            range: {
              from: fromIso ?? null,
              to: toIsoValue ?? null,
            },
            filter: {
              statuses: normalizedStatuses ?? null,
            },
            totals: {
              pending: 0,
              pending_allocation: 0,
              confirmed: 0,
              checked_in: 0,
              completed: 0,
              cancelled: 0,
              no_show: 0,
              PRIORITY_WAITLIST: 0,
            } as Record<OpsBookingStatus, number>,
            generatedAt: new Date().toISOString(),
          };
        }

        throw error;
      }
    },
    staleTime: 30_000,
  });
}

src/hooks/ops/useOpsBookingsList.ts:
'use client';

import { keepPreviousData, useQuery, type UseQueryResult } from '@tanstack/react-query';
import { useMemo } from 'react';

import { useBookingService } from '@/contexts/ops-services';
import { queryKeys } from '@/lib/query/keys';

import type { HttpError } from '@/lib/http/errors';
import type { OpsBookingsFilters, OpsBookingsPage } from '@/types/ops';

function toIsoString(value: Date | string | null | undefined): string | undefined {
  if (!value) return undefined;
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? undefined : value.toISOString();
  }

  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? undefined : parsed.toISOString();
}

function normalizeFilters(filters: OpsBookingsFilters) {
  const normalized: Record<string, string | number> = {
    restaurantId: filters.restaurantId,
  };

  if (filters.page) normalized.page = filters.page;
  if (filters.pageSize) normalized.pageSize = filters.pageSize;
  if (filters.status && filters.status !== 'all') normalized.status = filters.status;
  if (filters.statuses && filters.statuses.length > 0) normalized.statuses = filters.statuses.join(',');
  if (filters.sort) normalized.sort = filters.sort;
  if (filters.sortBy) normalized.sortBy = filters.sortBy;

  const fromIso = toIsoString(filters.from ?? undefined);
  if (fromIso) normalized.from = fromIso;

  const toIso = toIsoString(filters.to ?? undefined);
  if (toIso) normalized.to = toIso;

  const query = filters.query?.toString().trim();
  if (query) normalized.query = query;

  return normalized;
}

export function useOpsBookingsList(
  filters: OpsBookingsFilters | null,
): UseQueryResult<OpsBookingsPage, HttpError> {
  const bookingService = useBookingService();

  const normalizedFilters = useMemo(() => {
    if (!filters) return null;
    return normalizeFilters(filters);
  }, [filters]);

  const queryKey = normalizedFilters ? queryKeys.opsBookings.list(normalizedFilters) : queryKeys.opsBookings.list();

  return useQuery<OpsBookingsPage, HttpError>({
    queryKey,
    queryFn: () => {
      if (!filters) {
        throw new Error('Restaurant is required to fetch bookings');
      }
      return bookingService.listBookings(filters);
    },
    enabled: Boolean(filters?.restaurantId),
    placeholderData: keepPreviousData,
    staleTime: 30_000,
  });
}

src/hooks/ops/useOpsBookingsTableState.t:
'use client';

import { useDeferredValue, useEffect, useMemo, useState } from 'react';
import { create } from 'zustand';

import type { OpsBookingStatus } from '@/types/ops';

export type OpsStatusFilter = 'all' | 'upcoming' | 'past' | 'cancelled' | 'recent' | OpsBookingStatus;

export type UseOpsBookingsTableStateOptions = {
  initialStatus?: OpsStatusFilter;
  initialPage?: number;
  pageSize?: number;
  initialQuery?: string;
  initialSelectedStatuses?: OpsBookingStatus[];
};

type OpsBookingsTableStoreState = {
  statusFilter: OpsStatusFilter;
  page: number;
  search: string;
  selectedStatuses: OpsBookingStatus[];
  setStatusFilter: (next: OpsStatusFilter) => void;
  setPage: (next: number) => void;
  setSearch: (next: string) => void;
  toggleSelectedStatus: (status: OpsBookingStatus) => void;
  setSelectedStatuses: (next: OpsBookingStatus[]) => void;
  clearSelectedStatuses: () => void;
};

function createOpsBookingsTableStore(initial: {
  statusFilter: OpsStatusFilter;
  page: number;
  search: string;
  selectedStatuses: OpsBookingStatus[];
}) {
  return create<OpsBookingsTableStoreState>()((set, get) => ({
    ...initial,
    setStatusFilter: (next) => set({ statusFilter: next, page: 1 }),
    setPage: (next) => set({ page: next }),
    setSearch: (next) => set({ search: next, page: 1 }),
    toggleSelectedStatus: (status) => {
      const current = get().selectedStatuses;
      const exists = current.includes(status);
      const next = exists ? current.filter((value) => value !== status) : [...current, status];
      set({ selectedStatuses: next, page: 1 });
    },
    setSelectedStatuses: (next) => set({ selectedStatuses: next, page: 1 }),
    clearSelectedStatuses: () => set({ selectedStatuses: [], page: 1 }),
  }));
}

export function useOpsBookingsTableState({
  initialStatus = 'upcoming',
  initialPage = 1,
  pageSize = 10,
  initialQuery = '',
  initialSelectedStatuses = [],
}: UseOpsBookingsTableStateOptions = {}) {
  const [store] = useState(() =>
    createOpsBookingsTableStore({
      statusFilter: initialStatus,
      page: initialPage,
      search: initialQuery,
      selectedStatuses: initialSelectedStatuses,
    }),
  );

  useEffect(() => {
    store.setState({
      statusFilter: initialStatus,
      page: initialPage,
      search: initialQuery,
      selectedStatuses: initialSelectedStatuses,
    });
  }, [initialPage, initialQuery, initialSelectedStatuses, initialStatus, store]);

  const {
    statusFilter,
    page,
    search,
    selectedStatuses,
    setStatusFilter,
    setPage,
    setSearch,
    toggleSelectedStatus,
    setSelectedStatuses,
    clearSelectedStatuses,
  } = store();

  const handleStatusFilterChange = (nextStatus: OpsStatusFilter) => {
    setStatusFilter(nextStatus);
  };

  const handlePageChange = (nextPage: number, totalItems: number) => {
    if (Number.isNaN(nextPage)) return;
    const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
    const clamped = Math.min(Math.max(nextPage, 1), totalPages);
    setPage(clamped);
  };

  const handleSearchChange = (nextSearch: string) => {
    setSearch(nextSearch);
  };

  const deferredSearch = useDeferredValue(search.trim());

  const queryFilters = useMemo(() => {
    const now = new Date();
    const filters: {
      page: number;
      pageSize: number;
      status?: OpsBookingStatus;
      sort?: 'asc' | 'desc';
      from?: Date;
      to?: Date;
      query?: string;
      statuses?: OpsBookingStatus[];
      sortBy?: 'start_at' | 'created_at';
    } = {
      page,
      pageSize,
    };

    switch (statusFilter) {
      case 'upcoming':
        filters.from = now;
        filters.sort = 'asc';
        filters.sortBy = 'start_at';
        break;
      case 'past':
        filters.to = now;
        filters.sort = 'desc';
        filters.sortBy = 'start_at';
        break;
      case 'cancelled':
        filters.status = 'cancelled';
        filters.sort = 'desc';
        filters.sortBy = 'start_at';
        break;
      case 'recent':
        filters.sort = 'desc';
        filters.sortBy = 'created_at';
        break;
      case 'all':
        filters.sort = 'asc';
        filters.sortBy = 'start_at';
        break;
      default:
        filters.status = statusFilter as OpsBookingStatus;
        filters.sort = 'asc';
        filters.sortBy = 'start_at';
        break;
    }

    if (deferredSearch) {
      filters.query = deferredSearch;
    }

    if (selectedStatuses.length > 0) {
      filters.statuses = selectedStatuses;
    }

    return filters;
  }, [deferredSearch, page, pageSize, selectedStatuses, statusFilter]);

  return {
    statusFilter,
    page,
    pageSize,
    queryFilters,
    handleStatusFilterChange,
    handlePageChange,
    handleSearchChange,
    setStatusFilter,
    setPage,
    search,
    setSearch,
    selectedStatuses,
    toggleSelectedStatus,
    setSelectedStatuses,
    clearSelectedStatuses,
  } as const;
}

